class AuditTrail:
    def __init__(self):
        self.events: list[dict[str, object]] = []

    def record(self, event: str, **payload: object) -> None:
        self.events.append({"event": event, **payload})

    def count(self, event: str) -> int:
        return sum(1 for row in self.events if row["event"] == event)

    def for_record(self, record_id: str) -> list[dict[str, object]]:
        return [row for row in self.events if row.get("record_id") == record_id]

