class ManualClock:
    def __init__(self, now_ms: int = 0):
        self._now_ms = now_ms

    def now_ms(self) -> int:
        return self._now_ms

    def advance(self, ms: int) -> int:
        if ms < 0:
            raise ValueError("ms must be non-negative")
        self._now_ms += ms
        return self._now_ms

    def expired(self, deadline_ms: int | None) -> bool:
        return deadline_ms is not None and self._now_ms >= deadline_ms

