    def __init__(self, records: list[LeaseRecord] | None = None):
        self.records = {record.record_id: record for record in records or []}
        self.saved: list[dict[str, object]] = []
        self.read_count = 0
        self.write_count = 0
        self._token = 0

    def get(self, record_id: str) -> LeaseRecord:
