        return self.records[record_id]

    def next_token(self) -> int:
        self._token += 1
        return self._token

    def save(self, record: LeaseRecord) -> None:
        self.write_count += 1
        self.records[record.record_id] = record
        self.saved.append(record.to_dict())

    def guarded_save(self, record_id: str, owner: str, token: int, value: int, status: str) -> bool:
        record = self.records[record_id]
        record.owner = owner
        record.token = token
        record.value = value
        record.status = status
        self.save(record)
        return True

    def list_records(self) -> list[LeaseRecord]:
        self.read_count += 1
        return list(self.records.values())

