from lease_service import LeaseService

class LeaseWorkflow:
    def __init__(self, service: LeaseService, owner: str):
        self.service = service
        self.owner = owner

    def run_once(self, record_id: str, value: int, metadata: dict[str, object] | None = None) -> dict[str, object]:
        claim = self.service.acquire_lease(record_id, self.owner)
        return self.service.apply_lease(record_id, self.owner, int(claim["token"]), value, metadata)

    def run_many(self, record_ids: list[str], value: int) -> dict[str, object]:
        rows = [self.run_once(record_id, value) for record_id in record_ids]
        return {"count": len(rows), "rows": rows}

