from lease_models import LeaseRecord
from lease_repository import LeaseRepository
from lease_policy import LeasePolicy
from lease_service import LeaseService
from lease_adapter import ExternalAdapter
from lease_audit import AuditTrail
from lease_clock import ManualClock
from lease_workflow import LeaseWorkflow

def setup_service():
    repo=LeaseRepository([LeaseRecord("r1", "none"), LeaseRecord("r2", "none")])
    audit=AuditTrail() if "AuditTrail" in globals() else None
    adapter=ExternalAdapter() if "ExternalAdapter" in globals() else None
    clock=ManualClock(0) if "ManualClock" in globals() else None
    return repo, audit, adapter, LeaseService(repo, LeasePolicy(limit=100), audit, adapter, clock)

def test_first_acquire_returns_token():
    _,_,_,s=setup_service(); assert s.acquire_lease("r1","w1")["token"] == 1

def test_second_acquire_returns_newer_token():
    _,_,_,s=setup_service(); a=s.acquire_lease("r1","w1"); b=s.acquire_lease("r1","w2"); assert b["token"] > a["token"]

def test_stale_token_is_rejected():
    repo,_,_,s=setup_service(); a=s.acquire_lease("r1","w1"); s.acquire_lease("r1","w2"); assert s.apply_lease("r1","w1",a["token"],10)["ok"] is False

def test_wrong_owner_is_rejected():
    _,_,_,s=setup_service(); a=s.acquire_lease("r1","w1"); assert s.apply_lease("r1","w2",a["token"],10)["ok"] is False

def test_approved_updates_value():
    repo,_,_,s=setup_service(); a=s.acquire_lease("r1","w1"); s.apply_lease("r1","w1",a["token"],10); assert repo.get("r1").value == 10

def test_negative_value_denied():
    _,_,_,s=setup_service(); a=s.acquire_lease("r1","w1"); assert s.apply_lease("r1","w1",a["token"],-1)["status"] == "denied"

def test_over_limit_review():
    _,_,_,s=setup_service(); a=s.acquire_lease("r1","w1"); assert s.apply_lease("r1","w1",a["token"],150)["status"] == "review"

def test_blocked_metadata_denies():
    _,_,_,s=setup_service(); a=s.acquire_lease("r1","w1"); assert s.apply_lease("r1","w1",a["token"],10,{"blocked": True})["status"] == "denied"

def test_review_reason_retained():
    _,_,_,s=setup_service(); a=s.acquire_lease("r1","w1"); assert s.apply_lease("r1","w1",a["token"],10,{"review": True})["reasons"] == ["review"]

def test_adapter_not_called_for_denied():
    _,_,adapter,s=setup_service(); a=s.acquire_lease("r1","w1"); s.apply_lease("r1","w1",a["token"],-1); assert adapter.call_count() == 0

def test_audit_records_denial():
    _,audit,_,s=setup_service(); a=s.acquire_lease("r1","w1"); s.apply_lease("r1","w1",a["token"],-1); assert audit.count("denied") == 1

def test_workflow_runs_once():
    _,_,_,s=setup_service(); assert LeaseWorkflow(s,"w1").run_once("r1",10)["ok"] is True

def test_workflow_runs_many():
    _,_,_,s=setup_service(); assert LeaseWorkflow(s,"w1").run_many(["r1","r2"],10)["count"] == 2

def test_summary_payload_shape():
    _,_,_,s=setup_service(); assert set(s.summarize_lease()) == {"count","rows"}

def test_unrelated_record_unchanged():
    repo,_,_,s=setup_service(); a=s.acquire_lease("r1","w1"); s.apply_lease("r1","w1",a["token"],10); assert repo.get("r2").value == 0

def test_multiple_reasons_retained():
    _,_,_,s=setup_service(); a=s.acquire_lease("r1","w1"); assert set(s.apply_lease("r1","w1",a["token"],150,{"review": True})["reasons"]) == {"over_limit","review"}

def test_adapter_failure_does_not_save_success():
    repo,_,adapter,s=setup_service(); adapter.fail_next=True; a=s.acquire_lease("r1","w1")
    try:
        s.apply_lease("r1","w1",a["token"],10)
    except RuntimeError:
        pass
    else:
        raise AssertionError("expected RuntimeError")
    assert repo.get("r1").status != "approved"

def test_manual_clock_rejects_negative_advance():
    clock=ManualClock(0)
    try:
        clock.advance(-1)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")

def test_acquire_is_audited():
    _,audit,_,s=setup_service(); s.acquire_lease("r1","w1"); assert audit.for_record("r1")[0]["owner"] == "w1"

def test_result_payload_keys_stable():
    _,_,_,s=setup_service(); a=s.acquire_lease("r1","w1"); assert set(s.apply_lease("r1","w1",a["token"],10)) == {"ok","record_id","status","reasons"}
